// ---------------------------------------------------------------------------
// Prompt rendering
// ---------------------------------------------------------------------------

function fill(template: string, vars: Record<string, string>): string {
  return template.replace(/\{\{(\w+)\}\}/g, (_, k: string) => vars[k] ?? '');
}

function renderPrompt(
  targetLanguage: GeminiOcrInput['target_language'],
  responseFormat: GeminiOcrInput['response_format'],
  pageNumbers: number[],
): string {
  const rtlNote =
    targetLanguage === 'he' || targetLanguage === 'mixed'
      ? 'This document is (or contains) right-to-left Hebrew text. Preserve RTL reading order within each line; do not reverse or reorder characters/words. Mixed Hebrew/Latin lines (e.g. citations, transliterations) should be transcribed in the order a human reads them, not literal left-to-right byte order.'
      : '';
  const detailInstructions =
    responseFormat === 'detailed'
      ? 'Because response_format=detailed was requested, use the `notes` field generously: call out layout structure (columns, footnotes, marginalia, tables/figures), font-size or density issues that hurt legibility, and any passage where you are not confident in the transcription.'
      : 'Because response_format=concise was requested, keep `notes` brief — only flag genuinely low-confidence passages or anything a downstream editor must know about.';
  return fill(GEMINI_OCR_TEMPLATE, {
    target_language: targetLanguage,
    response_format: responseFormat,
    page_numbers: pageNumbers.join(', '),
    rtl_note: rtlNote,
    detail_instructions: detailInstructions,
  });
}

function stripFence(text: string): string {
  const fence = /```(?:json)?\s*\n([\s\S]*?)\n```/i.exec(text);
  return fence ? fence[1] : text;
}

// ---------------------------------------------------------------------------
// Main entry point
// ---------------------------------------------------------------------------

export async function runGeminiOcr(
  rawInput: unknown,
  deps: GeminiOcrDeps = defaultDeps(),
): Promise<GeminiOcrOutput> {
  const parsed = GeminiOcrInput.safeParse(rawInput);
  if (!parsed.success) {
    throw validation('Invalid input to gemini_ocr', { issues: parsed.error.issues }) as unknown as Error;
  }
  const input = parsed.data;

  assertOcrModelAllowed(OCR_MODEL); // always passes today; guards future regressions

  if (!(await deps.fileExists(input.document_path))) {
    throw validation(`document_path does not exist: ${input.document_path}`) as unknown as Error;
  }

  // Step 1: detect born-digital vs scan for every requested page in one pass.
  let detect: DetectResult;
  try {
    detect = await deps.runDetectTextLayer(input.document_path, input.page_range);
  } catch (err) {
    if (err && typeof err === 'object' && 'code' in err) throw err as unknown as Error;
    throw ocrFailed(
      `Failed to probe ${input.document_path} for a text layer: ${
        err instanceof Error ? err.message : String(err)
      }`,
    ) as unknown as Error;
  }

  // Step 2: batch math. Re-derive requestedPages from page_range + total_pages
  // (rather than trusting detect.pages' own filtering) so validation errors
  // (e.g. page_range beyond document length) surface consistently even if
  // the python side's own range validation is ever loosened independently.
  const requestedPages = parsePageRange(input.page_range, detect.total_pages);
  const plan = planBatch(requestedPages, 0, PER_CALL_PAGE_CAP);

  const detectByPage = new Map(detect.pages.map((p) => [p.page_number, p]));
  const pagesToProcess = plan.pagesToProcess;

  const bornDigitalPages: OcrPageResult[] = [];
  const scanPageNumbers: number[] = [];
  for (const pageNumber of pagesToProcess) {
    const d = detectByPage.get(pageNumber);
    if (!d) {
      throw ocrFailed(
        `detect_text_layer.py did not return a result for requested page ${pageNumber}.`,
      ) as unknown as Error;
    }
    if (d.is_born_digital) {
      bornDigitalPages.push({
        page_number: pageNumber,
        text: d.text,
        is_born_digital: true,
        confidence: 'high',
        notes: '',
      });
    } else {
      scanPageNumbers.push(pageNumber);
    }
  }

  // Step 3: OCR the scan pages in strictly sequential Gemini batches (C1).
  const ocrPages: OcrPageResult[] = [];
  const chunks = chunkForGeminiCalls(scanPageNumbers, GEMINI_BATCH_SIZE);
  for (const chunk of chunks) {
    // eslint-disable-next-line no-await-in-loop -- C1: sequential by design, never Promise.all
    const chunkResults = await ocrOneChunk(chunk, input, deps);
    ocrPages.push(...chunkResults);
  }

  const allPages = [...bornDigitalPages, ...ocrPages].sort((a, b) => a.page_number - b.page_number);

  const output: GeminiOcrOutput = {
    pages: allPages,
    truncated: plan.truncated,
  };
  if (plan.truncated && plan.truncationMessage) {
    output.truncation_message = plan.truncationMessage;
  }
  return GeminiOcrOutput.parse(output);
}

async function ocrOneChunk(
  chunk: number[],
  input: GeminiOcrInput,
  deps: GeminiOcrDeps,
): Promise<OcrPageResult[]> {
  if (chunk.length === 0) return [];

  const raster = await deps.runRasterizePages(input.document_path, chunk);
  // Files API uploads made for this chunk, tracked so they get deleted
  // (success or failure) in the `finally` below — uploaded files persist
  // ~48h server-side and count against the user's storage quota.
  const uploadedFileNames: string[] = [];
  try {
    // Read + base64-encode every page image in this chunk (needed for the
    // size decision regardless of which path is ultimately taken).
    const encoded = await Promise.all(raster.pages.map((p) => deps.readFileBase64(p.png_path)));
    const decision = decideUploadPath(encoded.map((e) => e.rawBytes));

    let images: OcrImagePart[];
    if (decision.useFilesApi) {
      // Chunk exceeds the inline threshold: upload each page's rasterized
      // PNG via the Files API and poll until ACTIVE, strictly sequentially
      // (mirrors C1 — never parallelize Gemini-facing calls). If upload/poll
      // itself errors (network failure, FAILED state, timeout), the error
      // propagates as an actionable ocr_failed (see uploadViaFilesApi) that
      // the /academic-writer:ocr skill's per-page-split fallback catches.
      images = [];
      for (const page of raster.pages) {
        // eslint-disable-next-line no-await-in-loop -- uploads must stay sequential (C1)
        const ref = await uploadViaFilesApi(page.png_path, 'image/png', {
          upload: deps.uploadFile,
          getStatus: deps.getUploadedFileStatus,
        });
        uploadedFileNames.push(ref.name);
        images.push({ mimeType: 'image/png', fileUri: ref.uri });
      }
    } else {
      images = encoded.map((e) => ({ mimeType: 'image/png', data: e.data }));
    }

    const promptText = renderPrompt(input.target_language, input.response_format, chunk);
    const mediaResolution = selectMediaResolution(input.response_format);

    // Part ordering: images before text (C6) — buildOcrParts documents why
    // this differs from write_section.ts's text-only convention. Exercised
    // here (and independently unit-tested) so the ordering rule can't
    // silently regress even though deps.generate builds its own `contents`.
    // Covers both inline (data) and Files API (fileUri) image shapes.
    const sdkShapedImages: ImagePart[] = images.map((img) =>
      img.fileUri
        ? { fileData: { mimeType: img.mimeType, fileUri: img.fileUri } }
        : { inlineData: { mimeType: img.mimeType, data: img.data ?? '' } },
    );
    const orderedParts = buildOcrParts(sdkShapedImages, promptText);
    if (
      images.length > 0 &&
      (orderedParts.length !== images.length + 1 ||
        !('inlineData' in orderedParts[0] || 'fileData' in orderedParts[0]))
    ) {
      throw ocrFailed('Internal error: OCR request parts were not image-first.');
    }

    const result = await deps.generate({ images, promptText, mediaResolution });

    const finishError: StructuredError | null = mapFinishReasonError(result.finishReason, chunk[0]);
    if (finishError) {
      throw finishError as unknown as Error;
    }

    let json: unknown;
    try {
      json = JSON.parse(stripFence(result.text));
    } catch (e) {
      throw ocrFailed(
        `Gemini returned non-JSON output for pages ${chunk.join(', ')}: ${
          e instanceof Error ? e.message : String(e)
        }`,
        { raw: result.text.slice(0, 1000) },
      ) as unknown as Error;
    }

    const arr = z.array(OcrPageResult).safeParse(json);
    if (!arr.success) {
      throw ocrFailed(`Gemini's OCR JSON for pages ${chunk.join(', ')} failed schema validation.`, {
        issues: arr.error.issues,
        raw: JSON.stringify(json).slice(0, 1000),
      }) as unknown as Error;
    }
    return arr.data;
  } finally {
    // Always clean up any Files API uploads for this chunk, success or
    // failure — a downstream failure (bad finishReason, JSON parse error,
    // schema validation) must not leak an ACTIVE uploaded file. Best-effort:
    // a delete failure here must not mask whatever error is already
    // propagating (or replace a clean success with a spurious failure).
    for (const name of uploadedFileNames) {
      // eslint-disable-next-line no-await-in-loop -- sequential cleanup, same as everything else in this chunk
      await deps.deleteUploadedFile(name).catch(() => {});
    }
    // Always clean up the rasterized temp dir, success or failure — no
    // unbounded /tmp litter (the flaw this staging pass was told to avoid).
    await deps.cleanupDir(raster.temp_dir);
  }
}

